import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<Map<String, Object>> entries) {
  var grouped = <String, List<Map<String, Object>>>{};
  for (var entry in entries) {
    String accountId = entry['accountId'] as String;
    grouped.putIfAbsent(accountId, () => []);
    grouped[accountId]!.add(entry);
  }

  var result = <String, int>{};
  grouped.forEach((accountId, accEntries) {
    var creditAmounts = <int>[];
    var debitAmounts = <int>[];
    for (var e in accEntries) {
      String type = e['type'] as String;
      int amount = e['amount'] as int;
      if (type == 'credit') {
        creditAmounts.add(amount);
      } else if (type == 'debit') {
        debitAmounts.add(amount);
      }
    }
    double median;
    if (creditAmounts.isEmpty) {
      median = 0.0;
    } else {
      creditAmounts.sort();
      int n = creditAmounts.length;
      if (n % 2 == 1) {
        median = creditAmounts[n ~/ 2].toDouble();
      } else {
        int mid1 = creditAmounts[(n ~/ 2) - 1];
        int mid2 = creditAmounts[n ~/ 2];
        median = (mid1 + mid2) / 2.0;
      }
    }
    double threshold = 10 * median;
    int count = 0;
    for (int amt in debitAmounts) {
      if (amt > threshold) {
        count++;
      }
    }
    result[accountId] = count;
  });
  return result;
}

