import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> initialMoisture, List<String> operations, int minMoisture, int maxMoisture) {
  List<int> moisture = List<int>.from(initialMoisture);
  List<List<int>> history = [];

  for (String op in operations) {
    if (op == 'UNDO') {
      if (history.isEmpty) {
        return false;
      }
      List<int> last = history.removeLast();
      moisture[last[0]] -= last[1];
      continue;
    }

    List<String> parts = op.split(' ');
    if (parts.length != 3) {
      return false;
    }

    int index = int.parse(parts[1]);
    int amount = int.parse(parts[2]);

    if (index < 0 || index >= moisture.length || amount < 0) {
      return false;
    }

    int delta;
    if (parts[0] == 'WATER') {
      delta = amount;
    } else if (parts[0] == 'DRY') {
      delta = -amount;
    } else {
      return false;
    }

    moisture[index] += delta;
    if (moisture[index] < minMoisture || moisture[index] > maxMoisture) {
      return false;
    }

    history.add([index, delta]);
  }

  return true;
}

