import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<int> strengths, int maxCombinedStrength) {
  if (strengths.isEmpty) return '0';
  var prevKeep = 0;
  var prevDisable = 1;
  for (var i = 1; i < strengths.length; i++) {
    final disable = 1 + (prevKeep < prevDisable ? prevKeep : prevDisable);
    var keep = prevDisable;
    if (strengths[i] + strengths[i - 1] <= maxCombinedStrength) {
      if (prevKeep < keep) {
        keep = prevKeep;
      }
    }
    prevKeep = keep;
    prevDisable = disable;
  }
  final best = prevKeep < prevDisable ? prevKeep : prevDisable;
  return '$best';
}

