import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String schedule) {
  if (schedule.isEmpty) return [];
  final result = <String>[];
  var current = schedule[0];
  var count = 1;
  for (var i = 1; i < schedule.length; i++) {
    if (schedule[i] == current) {
      count++;
    } else {
      result.add('$current$count');
      current = schedule[i];
      count = 1;
    }
  }
  result.add('$current$count');
  return result;
}

