import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> grid, int k) {
  int left = 0, right = grid.length - 1, result = -1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    int l = 0, r = grid[mid].length - 1, first = grid[mid].length;
    while (l <= r) {
      int m = l + (r - l) ~/ 2;
      if (grid[mid][m] == 1) { first = m; r = m - 1; } else { l = m + 1; }
    }
    if (grid[mid].length - first >= k) { result = mid; right = mid - 1; } else { left = mid + 1; }
  }
  return {"row": result};
}

