void fn0() {

  final int vertices = 5;
  final List<List<int>> graph = [
    [0, 2, 0, 6, 0],
    [2, 0, 3, 8, 5],
    [0, 3, 0, 0, 7],
    [6, 8, 0, 0, 9],
    [0, 5, 7, 9, 0]
  ];

  List<bool> inMST = List.filled(vertices, false);

  List<int> parent = List.filled(vertices, -1);

  List<int> key = List.filled(vertices, 999999);

  key[0] = 0;
  parent[0] = -1;

  for (int count = 0; count < vertices - 1; count++) {

    int minKey = 999999;
    int minVertex = -1;

    for (int v = 0; v < vertices; v++) {
      if (!inMST[v] && key[v] < minKey) {
        minKey = key[v];
        minVertex = v;
      }
    }

    inMST[minVertex] = true;

    for (int v = 0; v < vertices; v++) {



      if (graph[minVertex][v] != 0 && 
          !inMST[v] && 
          graph[minVertex][v] < key[v]) {
        parent[v] = minVertex;
        key[v] = graph[minVertex][v];
      }
    }
  }

  print('Prim\'s Minimum Spanning Tree:');
  print('Edge \t Weight');
  int totalWeight = 0;

  for (int i = 1; i < vertices; i++) {
    print('${parent[i]} - $i \t ${graph[i][parent[i]]}');
    totalWeight += graph[i][parent[i]];
  }

  print('\nTotal weight of MST: $totalWeight');

  print('\n--- Testing with a different graph ---');

  final int vertices2 = 6;
  final List<List<int>> graph2 = [
