  List<int> parent2 = List.filled(vertices2, -1);
  List<int> key2 = List.filled(vertices2, 999999);

  key2[0] = 0;
  parent2[0] = -1;

  for (int count = 0; count < vertices2 - 1; count++) {
    int minKey = 999999;
    int minVertex = -1;

    for (int v = 0; v < vertices2; v++) {
      if (!inMST2[v] && key2[v] < minKey) {
        minKey = key2[v];
        minVertex = v;
      }
    }

    inMST2[minVertex] = true;

    for (int v = 0; v < vertices2; v++) {
      if (graph2[minVertex][v] != 0 && 
          !inMST2[v] && 
          graph2[minVertex][v] < key2[v]) {
        parent2[v] = minVertex;
        key2[v] = graph2[minVertex][v];
