@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  String str1 = "AGGTAB";
  String str2 = "GXTXAYB";

  int m = str1.length;
  int n = str2.length;

  List<List<int>> dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (str1[i - 1] == str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = (dp[i - 1][j] > dp[i][j - 1]) ? dp[i - 1][j] : dp[i][j - 1];
      }
    }
  }

  print("Length of Longest Common Subsequence: ${dp[m][n]}");
}

