List<int> fn0(String trace) {
  final sizes = <int>[];
  for (final token in trace.split(' ')) {
    if (token.isEmpty) continue;
    final idx = token.indexOf(':');
    if (idx <= 0 || idx == token.length - 1) continue;
    final value = int.tryParse(token.substring(idx + 1));
    if (value != null) {
      sizes.add(value);
    }
  }
  return sizes;
}

