@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<int> nums = [10, 9, 2, 5, 3, 7, 101, 18];

  if (nums.isEmpty) {
    print('The length of the longest increasing subsequence is 0');
    return;
  }

  List<int> tails = List.filled(nums.length, 0);
  int len = 1;
  tails[0] = nums[0];

  for (int i = 1; i < nums.length; i++) {
    if (nums[i] < tails[0]) {

      tails[0] = nums[i];
    } else if (nums[i] > tails[len - 1]) {

      tails[len] = nums[i];
      len++;
    } else {

      int left = 0;
      int right = len;
      while (left < right) {
        int mid = left + (right - left) ~/ 2;
        if (tails[mid] < nums[i]) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }
      tails[left] = nums[i];
    }
  }

  print('The length of the longest increasing subsequence is $len');
}

