Map<String, int> fn0(List<String> events) {
  Map<String, int> wins = {};
  List<String> history = [];

  for (String event in events) {
    if (event == 'UNDO') {
      if (history.isNotEmpty) {
        String lastWinner = history.removeLast();
        int updated = (wins[lastWinner] ?? 0) - 1;

        if (updated <= 0) {
          wins.remove(lastWinner);
        } else {
          wins[lastWinner] = updated;
        }
      }
    } else {
      int split = event.indexOf('>');

      if (split > 0 && split < event.length - 1) {
        String winner = event.substring(0, split);
        history.add(winner);
        wins[winner] = (wins[winner] ?? 0) + 1;
      }
    }
  }

  return wins;
}

