import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> setpoints, int cycleMinutes) {
  int gcd(int a, int b) {
    a = a.abs();
    b = b.abs();
    while (b != 0) {
      int temp = a % b;
      a = b;
      b = temp;
    }
    return a;
  }

  bool isPrime(int value) {
    if (value < 2) {
      return false;
    }
    for (int i = 2; i * i <= value; i++) {
      if (value % i == 0) {
        return false;
      }
    }
    return true;
  }

  int syncStep = cycleMinutes.abs();
  int primeSetpoints = 0;
  int transitionCode = 0;

  for (int i = 0; i < setpoints.length; i++) {
    if (isPrime(setpoints[i])) {
      primeSetpoints++;
    }

    if (i > 0) {
      int diff = (setpoints[i] - setpoints[i - 1]).abs();
      if (diff != 0) {
        syncStep = gcd(syncStep, diff);
      }

      transitionCode = transitionCode * 2;
      if (setpoints[i] > setpoints[i - 1]) {
        transitionCode += 1;
      }
    }
  }

  return {
    'syncStep': syncStep,
    'primeSetpoints': primeSetpoints,
    'transitionCode': transitionCode,
  };
}

