    bool hasUpper = false, hasLower = false, hasDigit = false, hasSpecial = false;
    for (int c in p.codeUnits) {
      if (c >= 65 && c <= 90) hasUpper = true;
      else if (c >= 97 && c <= 122) hasLower = true;
      else if (c >= 48 && c <= 57) hasDigit = true;
      else hasSpecial = true;
    }
    return hasUpper && hasLower && hasDigit && hasSpecial;
  }

  Map<int, List<String>> groups = {};
  for (String p in passwords) {
    groups.putIfAbsent(p.length, () => []).add(p);
  }

  Map<int, String> mostCommonChar = {};
  groups.forEach((len, list) {
    Map<String, int> freq = {};
    for (String p in list) {
      for (String ch in p.split('')) {
        freq[ch] = (freq[ch] ?? 0) + 1;
      }
