    int maxFreq = -1;
    String chosen = '';
    freq.forEach((char, count) {
      if (count > maxFreq || (count == maxFreq && char.codeUnitAt(0) < chosen.codeUnitAt(0))) {
        maxFreq = count;
        chosen = char;
      }
    });
    mostCommonChar[len] = chosen;
  });

  int count = 0;
  for (String p in passwords) {
    if (isStrong(p)) {
      String common = mostCommonChar[p.length]!;
      if (!p.contains(common)) {
        count++;
      }
    }
  }
  return count;
}

