import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String misspelled, List<String> dictionary) {
  if (dictionary.isEmpty) return double.infinity;
  double score(String a, String b) {
    int minLen = a.length < b.length ? a.length : b.length;
    int subs = 0;
    for (int i = 0; i < minLen; i++) {
      if (a[i] != b[i]) subs++;
    }
    double deletions = (a.length - minLen) * 0.5;
    double insertions = (b.length - minLen) * 1.0;
    return subs * 0.5 + deletions + insertions;
  }
  List<String> sorted = List<String>.from(dictionary)
    ..sort((a, b) => score(misspelled, a).compareTo(score(misspelled, b)));
  return score(misspelled, sorted.first);
}

