import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String deck) {
  if (deck.trim().isEmpty) return 0.0;
  List<String> cards = deck.trim().split(RegExp(r'\s+'));
  int shift;
  String first = cards[0];
  String suitFirst = first.substring(first.length - 1);
  if (suitFirst == 'H') {
    shift = 1;
  } else if (suitFirst == 'D') {
    shift = 2;
  } else if (suitFirst == 'C') {
    shift = 3;
  } else if (suitFirst == 'S') {
    shift = 4;
  } else {
    shift = 0;
  }

  int total = 0;
  for (String card in cards) {
    String suit = card.substring(card.length - 1);
    String rankStr = card.substring(0, card.length - 1);
    int rank;
    switch (rankStr) {
      case 'A': rank = 1; break;
      case 'J': rank = 11; break;
      case 'Q': rank = 12; break;
      case 'K': rank = 13; break;
      default: rank = int.parse(rankStr); break;
    }
    int shiftedRank = ((rank - 1 + shift) % 13) + 1;
    int colorSign = (suit == 'H' || suit == 'D') ? 1 : -1;
    total += colorSign * shiftedRank;
  }

  return total / cards.length;
}

