@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> packageSizes, int basePerServing, int maxScale) {
  if (maxScale < 0) return {};
  if (basePerServing == 0) {
    Set<int> all = {};
    for (int s = 0; s <= maxScale; s++) all.add(s);
    return all;
  }
  int maxAmount = basePerServing * maxScale;
  List<bool> dp = List<bool>.filled(maxAmount + 1, false);
  dp[0] = true;
  for (int size in packageSizes) {
    if (size <= 0) continue;
    for (int j = size; j <= maxAmount; j++) {
      if (dp[j - size]) dp[j] = true;
    }
  }
  Set<int> result = {};
  for (int s = 0; s <= maxScale; s++) {
    if (dp[s * basePerServing]) result.add(s);
  }
  return result;
}

