import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> sortedWeights, List<int> priorities, int targetDiff, int minGap) {
  int n = sortedWeights.length;
  if (n < 2 || minGap >= n) return false;

  for (int i = 0; i <= n - 1 - minGap; i++) {
    int target = sortedWeights[i] + targetDiff;
    int startJ = i + minGap;

    if (target > sortedWeights[n - 1]) continue;
    if (target < sortedWeights[startJ]) continue;

    int lo = startJ;
    int hi = n - 1;
    int lowerBound = -1;
    while (lo <= hi) {
      int mid = lo + (hi - lo) ~/ 2;
      if (sortedWeights[mid] >= target) {
        lowerBound = mid;
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    }

    if (lowerBound == -1 || sortedWeights[lowerBound] != target) continue;

    lo = lowerBound;
    hi = n - 1;
    int upperBound = lowerBound;
    while (lo <= hi) {
      int mid = lo + (hi - lo) ~/ 2;
      if (sortedWeights[mid] <= target) {
        upperBound = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }

    for (int j = lowerBound; j <= upperBound; j++) {
      if (priorities[j] == priorities[i]) return true;
    }
  }

  return false;
}

