double fn0(String readings, String bin) {
  if (readings.isEmpty) return 0.0;
  final filtered = <int>[];
  for (final p in readings.split(',')) {
    final t = p.trim();
    if (t.isEmpty) continue;
    final v = int.parse(t);
    final match = bin == 'excellent' ? v >= -50 :
                  bin == 'good' ? v >= -67 && v < -50 :
                  bin == 'fair' ? v >= -80 && v < -67 :
                  bin == 'weak' ? v < -80 : false;
    if (match) filtered.add(v);
  }
  if (filtered.isEmpty) return 0.0;
  return filtered.reduce((a, b) => a + b) / filtered.length;
}

