import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> modules, int size) {
  if (modules.length <= 1) return 0.0;

  double centerX = size / 2.0;
  double centerY = size / 2.0;

  List<List<int>> sorted = [...modules];

  sorted.sort((a, b) {
    double distA = (a[0] - centerX).abs() + (a[1] - centerY).abs();
    double distB = (b[0] - centerX).abs() + (b[1] - centerY).abs();

    if (distA != distB) {
      return distA.compareTo(distB);
    }
    if (a[0] != b[0]) {
      return a[0].compareTo(b[0]);
    }
    return a[1].compareTo(b[1]);
  });

  int totalDistance = 0;
  for (int i = 1; i < sorted.length; i++) {
    totalDistance += (sorted[i][0] - sorted[i - 1][0]).abs();
    totalDistance += (sorted[i][1] - sorted[i - 1][1]).abs();
  }

  return totalDistance / (sorted.length - 1);
}

