import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> reservations) {
  if (reservations.isEmpty) {
    return '0@0';
  }

  List<List<int>> rects = [];
  List<int> xs = [];
  List<int> ys = [];

  for (String r in reservations) {
    List<int> p = r.split(',').map(int.parse).toList();
    int x1 = p[0];
    int y1 = p[1];
    int x2 = p[2];
    int y2 = p[3];

    if (x1 > x2) {
      int t = x1;
      x1 = x2;
      x2 = t;
    }
    if (y1 > y2) {
      int t = y1;
      y1 = y2;
      y2 = t;
    }

    if (x1 == x2 || y1 == y2) {
      continue;
    }

    rects.add([x1, y1, x2, y2]);
    xs.add(x1);
    xs.add(x2);
    ys.add(y1);
    ys.add(y2);
  }

  if (rects.isEmpty) {
    return '0@0';
  }

  xs = xs.toSet().toList()..sort();
  ys = ys.toSet().toList()..sort();

  Map<int, int> xi = {};
  Map<int, int> yi = {};

  for (int i = 0; i < xs.length; i++) {
    xi[xs[i]] = i;
  }
  for (int i = 0; i < ys.length; i++) {
    yi[ys[i]] = i;
  }

  List<List<int>> diff = List.generate(
    xs.length + 1,
    (_) => List.filled(ys.length + 1, 0),
  );

  for (List<int> r in rects) {
    int a = xi[r[0]]!;
    int b = yi[r[1]]!;
    int c = xi[r[2]]!;
    int d = yi[r[3]]!;

    diff[a][b]++;
    diff[c][b]--;
    diff[a][d]--;
    diff[c][d]++;
  }

  int area = 0;
  int maxOverlap = 0;

  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      int v = diff[i][j];
      if (i > 0) v += diff[i - 1][j];
      if (j > 0) v += diff[i][j - 1];
      if (i > 0 && j > 0) v -= diff[i - 1][j - 1];
      diff[i][j] = v;

      if (v > 0) {
        area += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
        if (v > maxOverlap) {
          maxOverlap = v;
        }
      }
    }
  }

  return '$area@$maxOverlap';
}

