import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(
    List<int> durations, List<int> moods, int targetDuration) {
  Set<int> participating = {};

  void backtrack(int idx, int currentSum, List<int> selected) {
    if (currentSum == targetDuration && selected.isNotEmpty) {
      bool compatible = true;
      for (int i = 1; i < selected.length; i++) {
        int diff = moods[selected[i]] - moods[selected[i - 1]];
        if (diff < 0) diff = -diff;
        if (diff > 2) {
          compatible = false;
          break;
        }
      }
      if (compatible) {
        for (int s in selected) {
          participating.add(s);
        }
      }
      return;
    }
    if (idx >= durations.length || currentSum > targetDuration) return;

    selected.add(idx);
    backtrack(idx + 1, currentSum + durations[idx], selected);
    selected.removeLast();

    backtrack(idx + 1, currentSum, selected);
  }

  backtrack(0, 0, []);
  return participating;
}

