Set<int> fn0(List<int> readings) {

  if (readings.isEmpty) return <int>{};
  var mask = readings.first;
  for (final r in readings) {
    mask &= r;
  }
  final positions = <int>{};
  var pos = 0;
  while (mask != 0) {
    if (mask & 1 == 1) positions.add(pos);
    mask >>= 1;
    pos++;
  }
  return positions;
}

