List<String> fn0(List<List<int>> grid) {
  List<String> corners = [];
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      int walls = grid[r][c] & 0xF;
      int count = 0;
      int v = walls;
      while (v > 0) {
        count += v & 1;
        v >>= 1;
      }
      if (count == 2) {
        bool adjacent = (walls & (walls >> 1)) != 0;
        bool wrapAdjacent = walls == 9; 
        if (adjacent || wrapAdjacent) {
          corners.add('$r,$c');
        }
      }
    }
  }
  return corners;
}

