@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<List<int>> playlists) {
  if (playlists.isEmpty) return [];
  final rows = playlists.length;
  final cols = playlists[0].length;
  final scores = <int>[];
  for (var r = 0; r < rows; r++) {
    var total = 0;
    for (var c = 0; c < cols; c++) {
      final val = playlists[r][c];
      var isPeak = false;
      if (r > 0 && c > 0) {
        if (val > playlists[r][c - 1] && val > playlists[r - 1][c]) {
          isPeak = true;
        }
      } else if (r > 0) {
        if (val > playlists[r - 1][c]) {
          isPeak = true;
        }
      } else if (c > 0) {
        if (val > playlists[r][c - 1]) {
          isPeak = true;
        }
      }
      total += isPeak ? val * 2 : val;
    }
    scores.add(total);
  }
  return scores;
}

