@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(
    List<int> containerIds,
    Map<int, int> priority,
    Map<int, int> weight,
    Set<int> hazardous) {
  List<int> sorted = List<int>.from(containerIds);
  sorted.sort((a, b) {
    bool hA = hazardous.contains(a);
    bool hB = hazardous.contains(b);
    if (hA != hB) return hA ? -1 : 1;
    int pA = priority[a] ?? 99;
    int pB = priority[b] ?? 99;
    if (pA != pB) return pA.compareTo(pB);
    int wA = weight[a] ?? 0;
    int wB = weight[b] ?? 0;
    if (wA != wB) return wB.compareTo(wA);
    return a.compareTo(b);
  });
  return sorted;
}

