import 'dart:async';
import 'dart:convert';
import 'dart:io';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<int>> getTranspose(int V, List<List<int>> graph) {
    List<List<int>> trans = List.generate(V, (_) => []);
    for (int u = 0; u < V; u++) {
      for (int v in graph[u]) {
        trans[v].add(u);
      }
    }
    return trans;
  }

  void dfsFirst(int u, List<bool> visited, List<List<int>> graph, List<int> stack) {
    visited[u] = true;
    for (int v in graph[u]) {
      if (!visited[v]) {
        dfsFirst(v, visited, graph, stack);
      }
    }
    stack.add(u);
  }

  void dfsSecond(int u, List<bool> visited, List<List<int>> graph, List<int> component) {
    visited[u] = true;
    component.add(u);
    for (int v in graph[u]) {
      if (!visited[v]) {
        dfsSecond(v, visited, graph, component);
      }
    }
  }

  int V = 5;
  List<List<int>> graph = List.generate(V, (_) => []);

  graph[0].add(1);
  graph[1].add(2);
  graph[2].add(3);
  graph[3].add(0);
  graph[1].add(4);

  List<int> stack = [];
  List<bool> visited = List<bool>.filled(V, false);
  for (int i = 0; i < V; i++) {
    if (!visited[i]) {
      dfsFirst(i, visited, graph, stack);
    }
  }

  List<List<int>> transpose = getTranspose(V, graph);

  visited = List<bool>.filled(V, false);
  List<List<int>> sccs = [];
  while (stack.isNotEmpty) {
    int u = stack.removeLast();
    if (!visited[u]) {
      List<int> component = [];
      dfsSecond(u, visited, transpose, component);
      sccs.add(component);
    }
  }

  print('Strongly Connected Components:');
  for (List<int> scc in sccs) {
    print(scc);
  }
}

