import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const int V = 4;

  List<List<double>> graph = List.generate(V, (_) => List.filled(V, double.infinity));

  for (int i = 0; i < V; i++) {
    graph[i][i] = 0;
  }

  graph[0][1] = 3;
  graph[0][2] = 5;
  graph[1][2] = -2; 
  graph[2][0] = 2;
  graph[2][3] = 3;
  graph[3][1] = 2;

  List<List<double>> dist = List.generate(V, (i) => List.from(graph[i]));

  for (int k = 0; k < V; k++) {
    for (int i = 0; i < V; i++) {
      for (int j = 0; j < V; j++) {
        if (dist[i][k] != double.infinity &&
            dist[k][j] != double.infinity &&
            dist[i][k] + dist[k][j] < dist[i][j]) {
          dist[i][j] = dist[i][k] + dist[k][j];
        }
      }
    }
  }

  bool hasNegativeCycle = false;
  for (int i = 0; i < V; i++) {
    if (dist[i][i] < 0) {
      hasNegativeCycle = true;
      break;
    }
  }

