import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String script) {
  if (script.isEmpty) {
    return <int>[];
  }

  List<int> rounds = <int>[];
  int score = 0;
  int lastDie = 0;
  bool doubleNext = false;

  for (int i = 0; i < script.length; i++) {
    String ch = script[i];

    if (ch.compareTo('1') >= 0 && ch.compareTo('6') <= 0) {
      int value = ch.codeUnitAt(0) - 48;
      if (doubleNext) {
        value *= 2;
        doubleNext = false;
      }
      score += value;
      lastDie = value;
    } else if (ch == '+') {
      doubleNext = true;
    } else if (ch == '!') {
      if (lastDie > 0) {
        score += lastDie;
      }
    } else if (ch == '-') {
      if (lastDie > 0) {
        score -= lastDie;
        lastDie = 0;
      }
    } else if (ch == '|') {
      rounds.add(score);
      score = 0;
      lastDie = 0;
      doubleNext = false;
    }
  }

  rounds.add(score);
  return rounds;
}

