import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> phases) {
  if (phases.isEmpty) return true;
  if (phases.length % 3 != 0) return false;

  final numCycles = phases.length ~/ 3;
  final greens = <int>[];
  final yellows = <int>[];
  final reds = <int>[];

  for (int i = 0; i < numCycles; i++) {
    final g = phases[i * 3];
    final y = phases[i * 3 + 1];
    final r = phases[i * 3 + 2];
    if (g <= 0 || y <= 0 || r <= 0) return false;
    greens.add(g);
    yellows.add(y);
    reds.add(r);
  }

  if (yellows.toSet().length != 1) return false;

  final totalGreen = greens.fold<int>(0, (sum, g) => sum + g);
  final totalRed = reds.fold<int>(0, (sum, r) => sum + r);
  if (totalGreen != totalRed) return false;

  for (int i = 1; i < greens.length; i++) {
    if (greens[i] < greens[i - 1]) return false;
  }

  for (int i = 1; i < reds.length; i++) {
    if (reds[i] > reds[i - 1]) return false;
  }

  final cycleTotals = List.generate(numCycles, (i) => greens[i] + yellows[i] + reds[i]);
  final minTotal = cycleTotals.reduce((a, b) => a < b ? a : b);
  for (final t in cycleTotals) {
    if (t > 2 * minTotal) return false;
  }

  return true;
}

