@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> grid) {
  List<int> result = List.filled(grid.length, 0);
  for (int i = 0; i < grid.length; i++) {
    int row = grid[i] & 0xFF;
    int count = 0;
    int temp = row;
    for (int j = 0; j < 8; j++) {
      count += temp & 1;
      temp >>= 1;
    }
    int rotated;
    if (count % 2 == 0) {
      rotated = ((row << 1) | (row >> 7)) & 0xFF;
    } else {
      rotated = ((row >> 1) | (row << 7)) & 0xFF;
    }
    result[i] = rotated;
  }
  return result;
}

