@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String barcode) {
  if (barcode.isEmpty) return 0;
  int maxLen = 0;
  for (int d1 = 0; d1 <= 9; d1++) {
    for (int d2 = d1 + 1; d2 <= 9; d2++) {
      final char1 = String.fromCharCode(d1 + 48);
      final char2 = String.fromCharCode(d2 + 48);
      int start = 0;
      while (start < barcode.length) {
        while (start < barcode.length && barcode[start] != char1 && barcode[start] != char2) {
          start++;
        }
        if (start >= barcode.length) break;
        int end = start;
        while (end < barcode.length && (barcode[end] == char1 || barcode[end] == char2)) {
          end++;
        }
        final segment = barcode.substring(start, end);
        final Map<int, int> prefixMap = {0: -1};
        int sum = 0;
        for (int i = 0; i < segment.length; i++) {
          if (segment[i] == char1) {
            sum += 1;
          } else {
            sum -= 1;
          }
          if (prefixMap.containsKey(sum)) {
            final length = i - prefixMap[sum]!;
            if (length > maxLen) maxLen = length;
          } else {
            prefixMap[sum] = i;
          }
        }
        start = end;
      }
    }
  }
  return maxLen;
}

