import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<int> rolls, int targetSum, int minRounds, int maxRounds, int requiredMax) {
  List<String> result = [];
  if (rolls.isEmpty || minRounds > maxRounds) return result;
  int n = rolls.length;
  int left = 0;
  int right = 0;
  int currentSum = 0;
  List<int> deque = [];
  int head = 0;

  while (left < n) {
    while (right < n && currentSum < targetSum) {
      while (head < deque.length && rolls[deque.last] <= rolls[right]) {
        deque.removeLast();
      }
      if (deque.isEmpty) head = 0;
      deque.add(right);
      currentSum += rolls[right];
      right++;
    }

    if (currentSum == targetSum) {
      int len = right - left;
      if (len >= minRounds && len <= maxRounds && head < deque.length) {
        int maxRoll = rolls[deque[head]];
        if (maxRoll >= requiredMax) {
          result.add("${left + 1}-${right}");
        }
      }
    }

    currentSum -= rolls[left];
    if (head < deque.length && deque[head] == left) {
      head++;
    }
    left++;
  }

  return result;
}

