import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {
  final int width = 20;
  final int height = 10;
  final Random rand = Random(0);

  const int N = 1, S = 2, E = 4, W = 8;
  final Map<int, int> dx = {E: 1, W: -1, N: 0, S: 0};
  final Map<int, int> dy = {E: 0, W: 0, N: -1, S: 1};
  final Map<int, int> opposite = {N: S, S: N, E: W, W: E};

  final grid = List.generate(
    height,
    (_) => List.filled(width, N | S | E | W),
  );

  final visited = List.generate(
    height,
    (_) => List.filled(width, false),
  );

  final stack = <Point<int>>[];

  visited[0][0] = true;
  stack.add(Point(0, 0));

  while (stack.isNotEmpty) {
    final current = stack.last;
    final x = current.x;
    final y = current.y;

    final neighbors = <int>[];
    for (final dir in [N, S, E, W]) {
      final nx = x + dx[dir]!;
      final ny = y + dy[dir]!;
      if (nx >= 0 &&
          nx < width &&
          ny >= 0 &&
          ny < height &&
          !visited[ny][nx]) {
        neighbors.add(dir);
      }
    }

    if (neighbors.isNotEmpty) {

      final dir = neighbors[rand.nextInt(neighbors.length)];
      final nx = x + dx[dir]!;
      final ny = y + dy[dir]!;

      grid[y][x] &= ~dir;
      grid[ny][nx] &= ~opposite[dir]!;

      visited[ny][nx] = true;
      stack.add(Point(nx, ny));
    } else {

      stack.removeLast();
    }
  }


  print(' ' + List.filled(width, '_').join());

  for (int y = 0; y < height; y++) {
    var line = '|';
    for (int x = 0; x < width; x++) {

      line += (grid[y][x] & S != 0) ? '_' : ' ';

      if (grid[y][x] & E != 0) {
        line += '|';
      } else {
        line += (grid[y][x] & S != 0) ? '_' : ' ';
      }
    }
    print(line);
  }
}

