import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> pixels) {
  final List<Map<String, Object>> parsed = [];

  for (final pixel in pixels) {
    final parts = pixel.split(',');
    if (parts.length != 3) {
      continue;
    }

    final r = int.tryParse(parts[0]);
    final g = int.tryParse(parts[1]);
    final b = int.tryParse(parts[2]);

    if (r == null || g == null || b == null) {
      continue;
    }
    if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
      continue;
    }

    final maxValue = [r, g, b].reduce((a, c) => a > c ? a : c);
    final minValue = [r, g, b].reduce((a, c) => a < c ? a : c);
    final spread = maxValue - minValue;
    final luminance = r * 3 + g * 4 + b * 2;

    String dominant = 'X';
    if (r > g && r > b) {
      dominant = 'R';
    } else if (g > r && g > b) {
      dominant = 'G';
    } else if (b > r && b > g) {
      dominant = 'B';
    }

    int delta = 0;
    if (dominant == 'R') {
      delta = g - b;
    } else if (dominant == 'G') {
      delta = b - r;
    } else if (dominant == 'B') {
      delta = r - g;
    }

    parsed.add({
      'raw': pixel,
      'r': r,
      'g': g,
      'b': b,
      'spread': spread,
      'lum': luminance,
      'dom': dominant,
      'delta': delta,
    });
  }

  const order = {'R': 0, 'G': 1, 'B': 2, 'X': 3};

  parsed.sort((a, b) {
    final spreadCompare = (b['spread'] as int).compareTo(a['spread'] as int);
    if (spreadCompare != 0) {
      return spreadCompare;
    }

    final lumCompare = (a['lum'] as int).compareTo(b['lum'] as int);
    if (lumCompare != 0) {
      return lumCompare;
    }

    final domCompare = (order[a['dom']]!).compareTo(order[b['dom']]!);
    if (domCompare != 0) {
      return domCompare;
    }

    final deltaCompare = (a['delta'] as int).compareTo(b['delta'] as int);
    if (deltaCompare != 0) {
      return deltaCompare;
    }

    return (a['raw'] as String).compareTo(b['raw'] as String);
  });

  return parsed
      .map((e) => '${e['dom']}@${e['r']},${e['g']},${e['b']}#${e['spread']}')
      .toList();
}

