int fn0(List<String> pallets) {
  if (pallets.isEmpty) return -1;
  final order = List<int>.generate(pallets.length, (i) => i);
  order.sort((a, b) {
    final pa = pallets[a].split(':');
    final pb = pallets[b].split(':');
    final zoneCmp = pa[0].compareTo(pb[0]);
    if (zoneCmp != 0) return zoneCmp;
    final shelfCmp = int.parse(pb[1]).compareTo(int.parse(pa[1]));
    if (shelfCmp != 0) return shelfCmp;
    return a.compareTo(b);
  });
  return order.first;
}

