List<String> fn0(String password, List<String> rlePatterns) {
  List<String> violations = [];
  for (String pattern in rlePatterns) {
    if (pattern.isEmpty) continue;
    StringBuffer decoded = StringBuffer();
    String countStr = '';
    for (int i = 0; i < pattern.length; i++) {
      String c = pattern[i];
      if (int.tryParse(c) != null) {
        countStr += c;
      } else {
        int count = countStr.isEmpty ? 1 : int.parse(countStr);
        decoded.write(c * count);
        countStr = '';
      }
    }
    String decodedStr = decoded.toString();
    if (decodedStr.isNotEmpty && password.contains(decodedStr)) {
      if (!violations.contains(decodedStr)) {
        violations.add(decodedStr);
      }
    }
  }
  violations.sort();
  return violations;
}

