@pragma('vm:entry-point')
Map<String, int> fn0(List<int> barcodes, int currentDay) {
  int expired = 0;
  int dueSoon = 0;
  int valid = 0;
  for (final b in barcodes) {
    final prodDay = b % 1000;
    final shelfLife = (b ~/ 1000) % 100;
    final expDay = prodDay + shelfLife;
    if (currentDay >= expDay) {
