import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> pricesInCents) {
  if (pricesInCents.isEmpty) return 0;
  Map<int, int> freq = {};
  for (int p in pricesInCents) {
    int r = p % 5;
    int rounded = r < 3 ? p - r : p + (5 - r);
    freq[rounded] = (freq[rounded] ?? 0) + 1;
  }
  int bestVal = -1;
  int bestCnt = 0;
  for (int key in freq.keys) {
    int cnt = freq[key]!;
    if (cnt > bestCnt || (cnt == bestCnt && key < bestVal)) {
      bestCnt = cnt;
      bestVal = key;
    }
  }
  return bestVal;
}

