import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {




  Map<int, List<int>> graph = {
    5: [2, 0],
    4: [0, 1],
    2: [3],
    3: [1],
    0: [],
    1: [],
  };

  void dfs(int node, Set<int> visited, List<int> stack) {
    visited.add(node);
    for (var neighbor in graph[node] ?? []) {
      if (!visited.contains(neighbor)) {
        dfs(neighbor, visited, stack);
      }
    }
    stack.add(node);
  }

  List<int> topologicalSort(Map<int, List<int>> graph) {
    Set<int> visited = {};
    List<int> stack = [];

    for (var node in graph.keys) {
      if (!visited.contains(node)) {
        dfs(node, visited, stack);
      }
    }

    return stack.reversed.toList();
  }

  List<int> sorted = topologicalSort(graph);
  print('Topological Sort: $sorted');
}

