import 'dart:async';
import 'dart:convert';
import 'dart:core';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  BigInt a, m;
  if (args.length >= 2) {
    try {
      a = BigInt.parse(args[0]);
      m = BigInt.parse(args[1]);
    } catch (e) {
      print('Invalid input. Usage: dart run script.dart <a> <m>');
      return;
    }
  } else {
    a = BigInt.from(42);
    m = BigInt.from(2017);
    print('No arguments provided. Using example values a=$a, m=$m');
  }

  if (m == BigInt.zero) {
    print('Modulus m must not be zero.');
    return;
  }

  final BigInt mod = m.abs();

  BigInt aNorm = a % mod;
  if (aNorm.isNegative) aNorm += mod;


  BigInt r0 = aNorm, r1 = mod;

  BigInt s0 = BigInt.one, s1 = BigInt.zero;
  BigInt t0 = BigInt.zero, t1 = BigInt.one;

  while (r1 != BigInt.zero) {
    final BigInt q = r0 ~/ r1;

    final BigInt r2 = r0 - q * r1;
    r0 = r1;
    r1 = r2;

    final BigInt s2 = s0 - q * s1;
    s0 = s1;
    s1 = s2;

    final BigInt t2 = t0 - q * t1;
    t0 = t1;
    t1 = t2;
  }

  final BigInt gcd = r0;

  if (gcd != BigInt.one) {
    print('No modular inverse exists because gcd(a, m) = $gcd != 1.');
    return;
  }

  BigInt inverse = s0 % mod;
  if (inverse.isNegative) inverse += mod;

  final BigInt check = (aNorm * inverse) % mod;

  print('a = $a');
  print('m = $m (using modulus |m| = $mod)');
  print('gcd(a, m) = $gcd');
  print('modInverse(a, m) = $inverse');
  print('Verification: (a mod |m|) * inverse mod |m| = $check'); 
}

