import 'dart:async';
import 'dart:convert';
import 'dart:math';

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final data = [
    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  final int k = 3; 
  final int maxIterations = 100;
  final random = Random(0);

  List<List<double>> centroids = [];
  final usedIndexes = <int>{};
  while (centroids.length < k) {
    int idx = random.nextInt(data.length);
    if (!usedIndexes.contains(idx)) {
      centroids.add(List.from(data[idx]));
      usedIndexes.add(idx);
    }
  }

  List<int> assignments = List.filled(data.length, -1);
  bool changed = true;
  int iterations = 0;

  double distance(List<double> a, List<double> b) {
    double sum = 0;
    for (int i = 0; i < a.length; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  while (changed && iterations < maxIterations) {
    changed = false;
    iterations++;

    for (int i = 0; i < data.length; i++) {
      double minDist = double.infinity;
      int bestCluster = -1;
      for (int c = 0; c < k; c++) {
        double dist = distance(data[i], centroids[c]);
        if (dist < minDist) {
          minDist = dist;
          bestCluster = c;
        }
      }
      if (assignments[i] != bestCluster) {
        assignments[i] = bestCluster;
        changed = true;
      }
    }

    List<List<double>> newCentroids =
        List.generate(k, (_) => List.filled(data[0].length, 0.0));
    List<int> counts = List.filled(k, 0);

    for (int i = 0; i < data.length; i++) {
      int cluster = assignments[i];
      for (int j = 0; j < data[i].length; j++) {
        newCentroids[cluster][j] += data[i][j];
      }
      counts[cluster]++;
    }

    for (int c = 0; c < k; c++) {
      if (counts[c] == 0) {

        newCentroids[c] = List.from(data[random.nextInt(data.length)]);
      } else {
        for (int j = 0; j < newCentroids[c].length; j++) {
          newCentroids[c][j] /= counts[c];
        }
      }
    }

    centroids = newCentroids;
  }

  for (int c = 0; c < k; c++) {
    print('Cluster $c:');
    for (int i = 0; i < data.length; i++) {
      if (assignments[i] == c) {
        print('  ${data[i]}');
      }
    }
    print('  Centroid: ${centroids[c]}');
  }
}

