import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> windowStarts, List<int> windowEnds, int k) {
  if (windowStarts.length != windowEnds.length || k < 0) {
    return {'windowIndex': -1, 'minute': -1};
  }
  if (windowStarts.isEmpty) {
    return {'windowIndex': -1, 'minute': -1};
  }

  List<List<int>> windows = [];
  for (int i = 0; i < windowStarts.length; i++) {
    int start = windowStarts[i];
    int end = windowEnds[i];
    if (end < start) {
      int temp = start;
      start = end;
      end = temp;
    }
    windows.add([start, end]);
  }

  windows.sort((a, b) => a[0].compareTo(b[0]));

  List<List<int>> merged = [];
  for (List<int> w in windows) {
    if (merged.isEmpty || w[0] > merged.last[1] + 1) {
      merged.add([w[0], w[1]]);
    } else if (w[1] > merged.last[1]) {
      merged.last[1] = w[1];
    }
  }

  List<int> prefix = [];
  int total = 0;
  for (List<int> w in merged) {
    total += w[1] - w[0] + 1;
    prefix.add(total);
  }

  if (k >= total) {
    return {'windowIndex': -1, 'minute': -1};
  }

  int left = 0;
  int right = prefix.length - 1;
  while (left < right) {
    int mid = left + ((right - left) >> 1);
    if (prefix[mid] > k) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }

  int previous = left == 0 ? 0 : prefix[left - 1];
  int offset = k - previous;
  int minute = merged[left][0] + offset;

  return {'windowIndex': left, 'minute': minute};
}

