import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String sequence) {
  String state = 'off';
  for (int i = 0; i < sequence.length; i++) {
    String cmd = sequence[i];
    switch (state) {
      case 'off':
        if (cmd == 'P') state = 'plugged';
        else if (cmd == 'S') state = 'off';
        else return false;
        break;
      case 'plugged':
        if (cmd == 'T') state = 'charging';
        else if (cmd == 'U') state = 'off';
        else if (cmd == 'P') state = 'plugged';
        else return false;
        break;
      case 'charging':
        if (cmd == 'T') state = 'full';
        else if (cmd == 'U') state = 'unplugged';
        else return false;
        break;
      case 'full':
        if (cmd == 'U') state = 'unplugged';
        else if (cmd == 'T') state = 'full';
        else return false;
        break;
      case 'unplugged':
        if (cmd == 'T') state = 'draining';
        else if (cmd == 'P') state = 'plugged';
        else return false;
        break;
      case 'draining':
        if (cmd == 'T') state = 'critical';
        else if (cmd == 'P') state = 'plugged';
        else return false;
        break;
      case 'critical':
        if (cmd == 'P') state = 'plugged';
        else if (cmd == 'S') state = 'off';
        else return false;
        break;
    }
  }
