import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(String decks) {
  if (decks.isEmpty) return {};
  final deckStrings = decks.split('|');
  Set<int>? common;
  for (final deckStr in deckStrings) {
    final cards = deckStr.split(',');
    final ranksInDeck = <int>{};
    for (final card in cards) {
      if (card.length < 2) continue;
      if (card == 'JK') continue;
      final rankChar = card[0];
      final suitChar = card[1];
      if (!{'C', 'D', 'H', 'S'}.contains(suitChar)) continue;
      int rank;
      switch (rankChar) {
        case 'A':
          rank = 1;
          break;
        case 'T':
          rank = 10;
          break;
        case 'J':
          rank = 11;
          break;
        case 'Q':
          rank = 12;
          break;
        case 'K':
          rank = 13;
          break;
        default:
          final parsed = int.tryParse(rankChar);
          if (parsed != null && parsed >= 2 && parsed <= 9) {
            rank = parsed;
          } else {
            continue;
          }
      }
      ranksInDeck.add(rank);
    }
    if (common == null) {
      common = ranksInDeck;
    } else {
      common = common.intersection(ranksInDeck);
    }
    if (common.isEmpty) break;
  }
  return common ?? {};
}

