import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(int trackCount, String commands) {
  if (trackCount <= 0) return "stopped:0";

  int state = 0;
  int track = 0;

  List<String> tokens = commands.split(' ');
  int i = 0;

  while (i < tokens.length) {
    String token = tokens[i];
    if (token.isEmpty) {
      i++;
      continue;
    }

    int count = 1;
    if (i + 1 < tokens.length) {
      int? parsed = int.tryParse(tokens[i + 1]);
      if (parsed != null && parsed > 0) {
        count = parsed;
        i++;
      }
    }

    for (int j = 0; j < count; j++) {
      if (token == 'play') {
        if (state != 1) state = 1;
      } else if (token == 'pause') {
        if (state == 1) {
          state = 2;
        } else if (state == 2) {
          state = 1;
        }
      } else if (token == 'next') {
        if (state == 1 || state == 2) {
          track = (track + 1) % trackCount;
        }
      } else if (token == 'prev') {
        if (state == 1 || state == 2) {
          track = (track - 1 + trackCount) % trackCount;
        }
      } else if (token == 'stop') {
        state = 0;
        break;
      }
    }
    i++;
  }

  String stateName = state == 0 ? 'stopped' : state == 1 ? 'playing' : 'paused';
  return '$stateName:$track';
}

