import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> quantities, List<int> scaleFactors, int k) {
  if (quantities.isEmpty || scaleFactors.isEmpty || k <= 0) return [];
  List<int> qs = List.from(quantities)..sort();
  List<int> ss = List.from(scaleFactors)..sort();
  int n = qs.length, m = ss.length, total = n * m;
  if (k > total) k = total;
  int lo = qs[0] * ss[0], hi = qs[n - 1] * ss[m - 1];
  while (lo < hi) {
    int mid = lo + (hi - lo) ~/ 2, count = 0;
    for (int i = 0; i < n; i++) {
      int maxS = mid ~/ qs[i], loS = 0, hiS = m - 1, idx = -1;
      while (loS <= hiS) {
        int midS = loS + (hiS - loS) ~/ 2;
        if (ss[midS] <= maxS) { idx = midS; loS = midS + 1; }
        else { hiS = midS - 1; }
      }
      count += idx + 1;
    }
    if (count >= k) hi = mid; else lo = mid + 1;
  }
  List<int> result = [];
  for (int i = 0; i < n; i++)
    for (int j = 0; j < m; j++) {
      int p = qs[i] * ss[j];
      if (p <= lo) result.add(p);
    }
  result.sort();
  return result.sublist(0, k);
}

