Map<String, int> fn0(List<String> items, Set<String> knownRarities) {
  Map<String, int> rarityCounts = {};
  Map<String, int> itemFrequency = {};
  for (var item in items) {
    itemFrequency[item] = (itemFrequency[item] ?? 0) + 1;
  }
  for (var entry in itemFrequency.entries) {
    String item = entry.key;
    int count = entry.value;
    int colonIndex = item.indexOf(':');
    String rarity;
    if (colonIndex != -1) {
      rarity = item.substring(0, colonIndex);
    } else {
      rarity = 'Unknown';
    }
    if (!knownRarities.contains(rarity)) {
      rarity = 'Unknown';
    }
    int bonus = count >= 3 ? count * 2 : count;
    rarityCounts[rarity] = (rarityCounts[rarity] ?? 0) + bonus;
  }
  return rarityCounts;
}

