import 'dart:async';
import 'dart:convert';
class FenwickTree {
  late List<int> tree;
  final int n;

  FenwickTree(this.n) {
    tree = List<int>.filled(n + 1, 0);
  }

  void update(int index, int val) {
    while (index <= n) {
      tree[index] += val;
      index += index & -index;
    }
  }

  int query(int index) {
    int sum = 0;
    while (index > 0) {
      sum += tree[index];
      index -= index & -index;
    }
    return sum;
  }
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  var ft = FenwickTree(10);

  ft.update(1, 5);
  ft.update(2, 3);
  ft.update(3, 7);
  ft.update(5, 2);
  ft.update(10, 1);

  print('Prefix sum up to 2: ${ft.query(2)}'); 
  print('Prefix sum up to 3: ${ft.query(3)}'); 
  print('Prefix sum up to 5: ${ft.query(5)}'); 
  print('Prefix sum up to 10: ${ft.query(10)}'); 

  ft.update(3, 4);

  print('Prefix sum up to 3 after update: ${ft.query(3)}'); 
  print('Prefix sum up to 10 after update: ${ft.query(10)}'); 
}

