import 'dart:async';
import 'dart:convert';
import 'dart:math' as math;

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {




  final data = <List<double>>[
    [1.0, 2.0],
    [1.2, 2.1],
    [0.8, 1.8],
    [8.0, 8.0],
    [8.2, 8.1],
    [100.0, 100.0], 
  ];

  const double eps = 0.5; 
  const int minPts = 2;   

  final int n = data.length;
  final visited  = List<bool>.filled(n, false);
  final cluster  = List<int>.filled(n, 0); 
  int clusterId  = 0;

  double distance(int i, int j) {
    double sum = 0.0;
    for (var k = 0; k < data[i].length; k++) {
      final diff = data[i][k] - data[j][k];
      sum += diff * diff;
    }
    return math.sqrt(sum);
  }

  List<int> regionQuery(int index) {
    final neighbors = <int>[];
    for (var j = 0; j < n; j++) {
      if (distance(index, j) <= eps) neighbors.add(j);
    }
    return neighbors;
  }

  void expandCluster(int index, List<int> neighbors) {
    cluster[index] = clusterId;
    final seeds = List<int>.from(neighbors);

    while (seeds.isNotEmpty) {
      final current = seeds.removeLast();

      if (!visited[current]) {
        visited[current] = true;
        final currentNeighbors = regionQuery(current);
        if (currentNeighbors.length >= minPts) {
          for (final nb in currentNeighbors) {
            if (!seeds.contains(nb)) seeds.add(nb);
          }
        }
      }

      if (cluster[current] == 0) {
        cluster[current] = clusterId;
      }
    }
  }


  for (var i = 0; i < n; i++) {
    if (visited[i]) continue;

    visited[i] = true;
    final neighbors = regionQuery(i);

    if (neighbors.length < minPts) {
      cluster[i] = -1; 
    } else {
