import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(int totalBytes, int mtu) {
  if (totalBytes <= 0 || mtu <= 0) return [];
  if (totalBytes <= mtu) return [totalBytes];
  List<int> fragments = [];
  int remaining = totalBytes;
  int packet = mtu;
  while (remaining > 0) {
    if (packet > remaining) {
      packet = remaining;
    }
    int g = packet;
    int t = remaining;
    while (t != 0) {
      int tmp = t;
      t = g % t;
      g = tmp;
    }
    if (g > 1) {
      packet = (packet ~/ g) * g;
      if (packet == 0) packet = g;
    }
    if (packet > remaining) packet = remaining;
    fragments.add(packet);
    remaining -= packet;
    if (remaining > 0 && packet > mtu ~/ 2) {
      packet = mtu;
    }
  }
  return fragments;
}

