List<int> fn0(String sequence) {
  List<String> stack = [];
  const Map<String, String> pairs = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'};
  for (int i = 0; i < sequence.length; i++) {
    String base = sequence[i];
    if (stack.isNotEmpty && pairs[stack.last] == base) {
      stack.removeLast();
    } else {
      stack.add(base);
    }
  }
  int a = 0, c = 0, g = 0, t = 0;
  for (String b in stack) {
    if (b == 'A') a++;
    else if (b == 'C') c++;
    else if (b == 'G') g++;
    else if (b == 'T') t++;
  }
  return [a, c, g, t];
}

