import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> phases, int emergencySkips) {
  String nextPhase(String phase) {
    if (phase == 'red') {
      return 'green';
    }
    if (phase == 'green') {
      return 'yellow';
    }
    return 'red';
  }

  bool search(int index, String previous, int skipsLeft) {
    if (index == phases.length) {
      return true;
    }

    String current = phases[index];

    if (previous.isEmpty || current == nextPhase(previous)) {
      if (search(index + 1, current, skipsLeft)) {
        return true;
      }
    }

    if (skipsLeft > 0) {
      return search(index + 1, previous, skipsLeft - 1);
    }

    return false;
  }

  return search(0, '', emergencySkips);
}

