import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> digits, int minimumDigit) {
  int left = 0;
  int right = digits.length - 1;
  int answer = -1;

  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (digits[mid] >= minimumDigit) {
      answer = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }

  if (answer == -1) {
    return {'index': -1, 'digit': -1};
  }
  return {'index': answer, 'digit': digits[answer]};
}

