import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String trace) {
  const suits = {'H', 'D', 'C', 'S'};
  const ranks = {'A', '2', '3', '4', '5', '6', '7', '8', '9', 'X', 'J', 'Q', 'K'};
  var state = 0;
  for (var i = 0; i < trace.length; i++) {
    final ch = trace[i];
    if (state == 0) {
      if (!suits.contains(ch)) return false;
      state = 1;
    } else {
      if (!ranks.contains(ch)) return false;
      state = 0;
    }
  }
  return state == 0 && trace.isNotEmpty;
}

