import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String encoded) {
  final out = <int>[];
  var n = 0, has = false;
  for (var i = 0; i < encoded.length; i++) {
    final c = encoded.codeUnitAt(i);
    if (c >= 48 && c <= 57) { n = n * 10 + c - 48; has = true; continue; }
    final t = c == 87 ? 0 : c == 79 ? 1 : c == 83 ? 2 : c == 69 ? 3 : -1;
    if (t < 0) { n = 0; has = false; continue; }
    for (var j = 0, r = has ? n : 1; j < r; j++) out.add(t);
    n = 0; has = false;
  }
  return out;
}

