import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<String> logLines) {
  final Map<String, int> maxRunLengths = {};
  final Map<String, int> currentRunLengths = {};
  int? lastDuration;
  String? lastLevel;

  for (final line in logLines) {
    final parts = line.split(' ');
    if (parts.length != 3) continue;

    final level = parts[1];
    final duration = int.tryParse(parts[2]);

    if (duration == null || duration < 0) continue;

    if (level == lastLevel && lastDuration != null && duration > lastDuration) {
      currentRunLengths[level] = (currentRunLengths[level] ?? 1) + 1;
    } else {
      currentRunLengths[level] = 1;
    }

    final currentRun = currentRunLengths[level]!;
    if ((maxRunLengths[level] ?? 0) < currentRun) {
      maxRunLengths[level] = currentRun;
    }

    lastLevel = level;
    lastDuration = duration;
  }

  final sortedLevels = maxRunLengths.keys.toList()..sort();
  return sortedLevels.map((level) => maxRunLengths[level]!).toList();
}

