import 'dart:async';
import 'dart:convert';
@pragma('vm:entry-point')
/// Checks whether any barcode bar (at y=0, x from barXPositions)
/// is within Manhattan distance of BOTH scanners simultaneously.
/// Scanner i at (six, siy) has range sir.
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> barXPositions, int s1x, int s1y, int s1r, int s2x, int s2y, int s2r) {
  for (int bx in barXPositions) {
    int d1 = (s1x - bx).abs() + s1y.abs();
    int d2 = (s2x - bx).abs() + s2y.abs();
    if (d1 <= s1r && d2 <= s2r) {
      return true;
    }
  }
  return false;
}

