String fn0(int barcode, int currentDay) {
  int dayIndex = barcode ~/ 100;
  int remainder = barcode % 100;
  int shelfBaseDigit = remainder ~/ 10;
  int freshnessDigit = remainder % 10;

  int baseDays;
  switch (shelfBaseDigit) {
    case 0: baseDays = 3; break;
    case 1: baseDays = 5; break;
    case 2: baseDays = 7; break;
    case 3: baseDays = 10; break;
    case 4: baseDays = 14; break;
    case 5: baseDays = 21; break;
    case 6: baseDays = 30; break;
    case 7: baseDays = 45; break;
    case 8: baseDays = 60; break;
    case 9: baseDays = 90; break;
    default: baseDays = 0;
  }

  int shelfLife = baseDays;
  if (freshnessDigit <= 2) {

  } else if (freshnessDigit <= 5) {
    shelfLife = (baseDays * 3) ~/ 2;
  } else {
    shelfLife = (baseDays * 7) ~/ 10;
  }

  int expiryDay = dayIndex + shelfLife;
  int diff = expiryDay - currentDay;

  if (diff > 0) {
    return diff == 1 ? "Valid: 1 day remaining" : "Valid: $diff days remaining";
  } else if (diff < 0) {
    int absDiff = -diff;
    return absDiff == 1 ? "Expired: 1 day ago" : "Expired: $absDiff days ago";
  } else {
    return "Expires today!";
  }
}

