import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> events) {
  final votes = <int>[];
  final valid = <bool>[];
  final challenges = <int>[];

  for (final event in events) {
    if (event > 0) {
      votes.add(event);
      valid.add(true);
    } else if (event == 0) {
      for (int i = votes.length - 1; i >= 0; i--) {
        if (valid[i]) {
          valid[i] = false;
          challenges.add(i);
          break;
        }
      }
    } else if (event == -1) {
      if (challenges.isNotEmpty) {
        final idx = challenges.removeAt(0);
        final cand = votes[idx];
        int totalValid = 0;
        int candValid = 0;
        for (int i = 0; i < votes.length; i++) {
          if (valid[i]) {
            totalValid++;
            if (votes[i] == cand) candValid++;
          }
        }
        if (candValid * 2 > totalValid) {
          valid[idx] = true;
        }
      }
    } else if (event == -2) {
      for (final idx in challenges) {
        valid[idx] = true;
      }
      challenges.clear();
    }
  }

  int count = 0;
  for (final v in valid) if (v) count++;
  return count;
}

