@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  void generateCombinations(List<int> items, int k, int start, List<int> current, List<List<int>> result) {
    if (current.length == k) {
      result.add(List.from(current)); 
      return;
    }
    for (int i = start; i < items.length; i++) {
      current.add(items[i]);
      generateCombinations(items, k, i + 1, current, result);
      current.removeLast(); 
    }
  }

  List<int> items = [1, 2, 3, 4];
  int k = 2;
  List<List<int>> combinations = [];
  generateCombinations(items, k, 0, [], combinations);

  print('Combinations of $items taken $k at a time:');
  for (var combo in combinations) {
    print(combo);
  }
}

