      depth[u] = depth[v] + 1;
      dfs(u, v);
      size[v] += size[u];
      if (size[u] > maxSubtree) {
        maxSubtree = size[u];
        heavy[v] = u;
      }
    }
  }

  void decompose(int v, int h) {
    head[v] = h;
    pos[v] = curPos++;
    if (heavy[v] != -1) {
      decompose(heavy[v], h);
    }
    for (int u in tree[v]) {
      if (u != parent[v] && u != heavy[v]) {
        decompose(u, u);
      }
    }
  }

