  decompose(1, 1);

  print('Node | Parent | Depth | Heavy | Head | Pos');
  for (int v = 1; v <= n; ++v) {
    print(
        '$v\t| ${parent[v]}\t| ${depth[v]}\t| ${heavy[v] == -1 ? "-" : heavy[v]}\t| ${head[v]}\t| ${pos[v]}');
  }

  List<List<int>> getPathSegments(int u, int v) {
    List<List<int>> res = [];
    while (head[u] != head[v]) {
      if (depth[head[u]] < depth[head[v]]) {
        int tmp = u;
        u = v;
        v = tmp;
      }
      res.add([head[u], pos[head[u]], pos[u]]);
      u = parent[head[u]];
    }
    if (depth[u] > depth[v]) {
      int tmp = u;
      u = v;
      v = tmp;
    }
    res.add([head[u], pos[u], pos[v]]);
    return res;
  }

  int u = 4, v = 7;
  print('\nPath segments from $u to $v:');
  var segments = getPathSegments(u, v);
  for (var seg in segments) {
    print('Chain head: ${seg[0]}, pos: ${seg[1]} to ${seg[2]}');
  }
