String fn0(List<int> heights) {
  if (heights.isEmpty) return '0';
  int n = heights.length;
  if (n == 1) return '1';
  int maxLen = 1;
  int up = 1;
  int down = 1;
  for (int i = 1; i < n; i++) {
    if (heights[i] > heights[i - 1]) {
      up = down + 1;
      down = 1;
    } else if (heights[i] < heights[i - 1]) {
      down = up + 1;
      up = 1;
    } else {
      up = 1;
      down = 1;
    }
    if (up > maxLen) maxLen = up;
    if (down > maxLen) maxLen = down;
  }
  return maxLen.toString();
}

