@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String barcode) {
  List<int> result = [];
  List<String> segments = barcode.split('-');
  for (String seg in segments) {
    if (seg.length < 2) continue;
    bool allDigits = true;
    for (int i = 0; i < seg.length; i++) {
      int code = seg.codeUnitAt(i);
      if (code < 48 || code > 57) {
        allDigits = false;
        break;
      }
    }
    if (!allDigits) continue;
    int alternatingSum = 0;
    for (int i = 0; i < seg.length - 1; i++) {
      int digit = seg.codeUnitAt(i) - 48;
      if (i % 2 == 0) {
        alternatingSum += digit;
      } else {
        alternatingSum += digit * 3;
      }
    }
    int expectedChecksum = (10 - (alternatingSum % 10)) % 10;
    int lastDigit = seg.codeUnitAt(seg.length - 1) - 48;
    if (lastDigit == expectedChecksum) {
      result.add(int.parse(seg));
    }
  }
  return result;
}

