@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<int> cents) {
  if (cents.isEmpty) return {"length": 0, "startIndex": -1};
  int maxLen = 0;
  int maxStart = 0;
  int i = 0;
  int _round5(int c) {
    int rem = c % 5;
    return rem <= 2 ? c - rem : c + (5 - rem);
  }
  int currentRounded = _round5(cents[0]);
  for (int j = 0; j < cents.length; j++) {
    int rounded = _round5(cents[j]);
    if (rounded != currentRounded) {
      i = j;
      currentRounded = rounded;
    }
    int len = j - i + 1;
    if (len > maxLen) {
      maxLen = len;
      maxStart = i;
    }
  }
  return {"length": maxLen, "startIndex": maxStart};
}

