import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> ingredientUnits, int targetUnits, int maxRepeatedSize) {
  if (targetUnits < 0 || maxRepeatedSize < 1) {
    return false;
  }

  Map<int, int> counts = {};
  int left = 0;
  int currentTotal = 0;

  for (int right = 0; right < ingredientUnits.length; right++) {
    int value = ingredientUnits[right];
    currentTotal += value;
    counts[value] = (counts[value] ?? 0) + 1;

    while (left <= right &&
        (currentTotal > targetUnits ||
            (counts[value] ?? 0) > maxRepeatedSize)) {
      int removed = ingredientUnits[left];
      currentTotal -= removed;
      counts[removed] = (counts[removed] ?? 0) - 1;

      if (counts[removed] == 0) {
        counts.remove(removed);
      }

      left++;
    }

    if (currentTotal == targetUnits) {
      return true;
    }
  }

  return false;
}

