@pragma('vm:entry-point')
bool fn0(List<int> bucketCounts, int minLen, double targetAvg) {
  int n = bucketCounts.length;
  if (minLen <= 0 || n < minLen) return false;

  List<double> prefix = List<double>.filled(n + 1, 0.0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + bucketCounts[i] - targetAvg;
  }

  double minPrefix = prefix[0];
  for (int i = minLen; i <= n; i++) {
    if (prefix[i] - minPrefix >= 0) return true;
    if (prefix[i - minLen + 1] < minPrefix) {
      minPrefix = prefix[i - minLen + 1];
    }
  }

  return false;
}

