  if (readings.isEmpty) {
    return {'longestRise': 0, 'longestDrop': 0};
  }
  int rise = 1, drop = 1, bestRise = 1, bestDrop = 1;
  for (int i = 1; i < readings.length; i++) {
    rise = readings[i] > readings[i - 1] ? rise + 1 : 1;
    drop = readings[i] < readings[i - 1] ? drop + 1 : 1;
    if (rise > bestRise) bestRise = rise;
    if (drop > bestDrop) bestDrop = drop;
  }
  return {'longestRise': bestRise, 'longestDrop': bestDrop};
}

