@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String password, int modulus) {
  final violations = <String>[];
  if (modulus < 2) {
    violations.add('invalidModulus');
    return violations;
  }
  final factors = <int>{};
  int n = modulus;
  for (int i = 2; i <= n ~/ i; i++) {
    if (n % i == 0) {
      factors.add(i);
      do { n ~/= i; } while (n % i == 0);
    }
  }
  if (n > 1) factors.add(n);
  final isPrime = factors.length == 1 && factors.contains(modulus);
  int a = password.length, b = modulus;
  while (b != 0) { final t = b; b = a % b; a = t; }
  if (a != 1) violations.add('lengthNotCoprime');
  bool shares = false;
  for (final c in password.codeUnits) {
    for (final p in factors) {
      if (c % p == 0) { shares = true; break; }
    }
    if (shares) break;
  }
  if (shares) violations.add('charCodeSharesFactor');
  if (!isPrime) {
    violations.add('modulusNotPrime');
  } else {
    int sum = 0;
    for (final c in password.codeUnits) sum += c;
    int s = sum % modulus;
    if (s != 0) {
      int e = (modulus - 1) ~/ 2, base = s, res = 1;
      while (e > 0) {
        if ((e & 1) == 1) res = (res * base) % modulus;
        base = (base * base) % modulus;
        e >>= 1;
      }
      if (res != 1) violations.add('sumNotQuadraticResidue');
    }
  }
  return violations;
}

