Set<int> fn0(List<String> phases) {
  final List<MapEntry<String, int>> runs = [];
  if (phases.isEmpty) return <int>{};
  String current = phases[0];
  int count = 1;
  for (int i = 1; i < phases.length; i++) {
    if (phases[i] == current) {
      count++;
    } else {
      runs.add(MapEntry(current, count));
      current = phases[i];
      count = 1;
    }
  }
  runs.add(MapEntry(current, count));
  final Map<int, Set<String>> durationToColors = {};
  for (final run in runs) {
    final color = run.key;
    final duration = run.value;
    durationToColors.putIfAbsent(duration, () => <String>{});
    durationToColors[duration]!.add(color);
  }
  final Set<int> shared = {};
  for (final entry in durationToColors.entries) {
    if (entry.value.length > 1) {
      shared.add(entry.key);
    }
  }
  return shared;
}

