import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> chart, int people) {
  if (chart.isEmpty) {
    return <int>{};
  }

  final int rows = chart.length;
  final int cols = chart[0].length;
  final List<int> available = <int>[];

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (chart[r][c] == '.') {
        available.add(r * cols + c);
      }
    }
  }

  Set<int>? intersection;
  int solutions = 0;

  bool touches(int a, int b) {
    final int ar = a ~/ cols;
    final int ac = a % cols;
    final int br = b ~/ cols;
    final int bc = b % cols;
    return (ar == br && (ac - bc).abs() == 1) ||
        (ac == bc && (ar - br).abs() == 1);
  }

  void search(int index, List<int> chosen) {
    if (chosen.length == people) {
      final Set<int> current = chosen.toSet();
      if (intersection == null) {
        intersection = current;
      } else {
        intersection = intersection!.intersection(current);
      }
      solutions++;
      return;
    }

    if (index >= available.length ||
        chosen.length + (available.length - index) < people) {
      return;
    }

    final int seat = available[index];
    bool allowed = true;

    for (final int taken in chosen) {
      if (touches(seat, taken)) {
        allowed = false;
        break;
      }
    }

    if (allowed) {
      chosen.add(seat);
      search(index + 1, chosen);
      chosen.removeLast();
    }

    search(index + 1, chosen);
  }

  search(0, <int>[]);
  return solutions == 0 ? <int>{} : intersection!;
}

