import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> signals, int binWidth, int modulus) {
  if (binWidth <= 0 || modulus <= 1) {
    return -1.0;
  }

  if (signals.isEmpty) {
    return 0.0;
  }

  int gcd(int a, int b) {
    a = a.abs();
    b = b.abs();
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  int modPow(int base, int exponent, int mod) {
    int result = 1 % mod;
    int current = base % mod;

    while (exponent > 0) {
      if (exponent.isOdd) {
        result = (result * current) % mod;
      }
      current = (current * current) % mod;
      exponent ~/= 2;
    }

    return result;
  }

  Map<int, int> counts = {};
  for (int signal in signals) {
    int bin = (signal + 120) ~/ binWidth;
    counts[bin] = (counts[bin] ?? 0) + 1;
  }

  List<int> bins = counts.keys.toList()..sort();

  int spacingGcd = 0;
  for (int i = 1; i < bins.length; i++) {
    int diff = (bins[i] - bins[i - 1]).abs();
    spacingGcd = spacingGcd == 0 ? diff : gcd(spacingGcd, diff);
  }

  if (spacingGcd == 0) {
    spacingGcd = 1;
  }

  int modularScore = 0;
  for (int bin in bins) {
    int count = counts[bin]!;
    int base = ((bin % modulus) + modulus) % modulus + 1;
    int exponent = count + spacingGcd;
    int value = modPow(base, exponent, modulus);
    modularScore = (modularScore + value + count) % modulus;
  }

  int finalInt = (modularScore + spacingGcd + bins.length) % 64;
  return finalInt / 4.0;
}

