import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String hierarchy) {
  if (hierarchy.isEmpty) return [];
  final sums = <int>[];
  int parseNode(int index, int depth) {
    int start = index;
    while (index < hierarchy.length) {
      int code = hierarchy.codeUnitAt(index);
      if (code < 48 || code > 57) break;
      index++;
    }
    int value = int.parse(hierarchy.substring(start, index));
    if (depth >= sums.length) {
      sums.add(value);
    } else {
      sums[depth] += value;
    }
    if (index < hierarchy.length && hierarchy[index] == '(') {
      index++; 
      while (true) {
        index = parseNode(index, depth + 1);
        if (index < hierarchy.length && hierarchy[index] == ',') {
          index++;
        } else if (index < hierarchy.length && hierarchy[index] == ')') {
          index++;
          break;
        } else {
          break;
        }
      }
    }
    return index;
  }
  parseNode(0, 0);
  return sums;
}

