import 'dart:async';
import 'dart:convert';
@pragma('vm:entry-point')
/// Checks if two adjacent maze cells have an open passage between them.
/// Walls are encoded as 4 bits: bit0=North, bit1=East, bit2=South, bit3=West.
/// A bit value of 1 means the wall is present; 0 means open.
/// Direction: 0=North, 1=East, 2=South, 3=West.
/// A passage exists only if BOTH cells have the shared wall removed.
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(int cell1Walls, int cell2Walls, int direction) {

  int oppositeDir = direction ^ 2;

  int cell1WallBit = 1 << direction;
  bool cell1HasOpening = (cell1Walls & cell1WallBit) == 0;

  int cell2WallBit = 1 << oppositeDir;
  bool cell2HasOpening = (cell2Walls & cell2WallBit) == 0;

  return cell1HasOpening && cell2HasOpening;
}

