@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String readings) {
  if (readings.trim().isEmpty) {
    return "E:0,G:0,F:0,W:0";
  }

  List<String> tokens = readings.split(',');
  int excellent = 0;
  int good = 0;
  int fair = 0;
  int weak = 0;

  for (String token in tokens) {
    String trimmed = token.trim();
    if (trimmed.isEmpty) continue;
    int? value = int.tryParse(trimmed);
    if (value == null) continue;
    if (value >= -30) {
      excellent++;
    } else if (value >= -60) {
      good++;
    } else if (value >= -80) {
      fair++;
    } else {
      weak++;
    }
  }

  return "E:$excellent,G:$good,F:$fair,W:$weak";
}

