@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> orders) {
  Set<int> possible = {0};
  for (int order in orders) {
    Set<int> next = {};
    int half = order ~/ 2;
    for (int total in possible) {
      next.add(total + order);
      next.add(total + half);
    }
    possible = next;
  }
  return possible;
}

