import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  String customJsonEncode(dynamic obj) {
    if (obj == null) {
      return 'null';
    } else if (obj is bool) {
      return obj ? 'true' : 'false';
    } else if (obj is num) {
      return obj.toString();
    } else if (obj is String) {

      String escaped = obj
          .replaceAll('\\', '\\\\')
          .replaceAll('"', '\\"')
          .replaceAll('\n', '\\n')
          .replaceAll('\r', '\\r')
          .replaceAll('\t', '\\t');
      return '"$escaped"';
    } else if (obj is List) {
      List<String> encodedItems = obj.map((item) => customJsonEncode(item)).toList();
      return '[${encodedItems.join(',')}]';
    } else if (obj is Map) {
      List<String> encodedEntries = [];
      obj.forEach((key, value) {
        if (key is! String) {
          throw Exception('Map keys must be strings for JSON encoding');
        }
        encodedEntries.add('${customJsonEncode(key)}:${customJsonEncode(value)}');
      });
      return '{${encodedEntries.join(',')}}';
    } else {
      throw Exception('Unsupported type for JSON encoding: ${obj.runtimeType}');
    }
  }

  Map<String, dynamic> sample = {
    'name': 'John Doe',
    'age': 30,
    'isStudent': false,
    'hobbies': ['reading', 'gaming'],
    'address': null,
    'quote': 'He said, "Hello!"\nNew line.'
  };

  String jsonString = customJsonEncode(sample);
  print(jsonString);
}

