import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> initialBuckets, List<String> operations) {
  List<int> buckets = List<int>.from(initialBuckets);
  List<Object> stack = [];
  int maxCount = 0;
  if (buckets.isNotEmpty) {
    maxCount = buckets.reduce((a, b) => a > b ? a : b);
  }
  for (String op in operations) {
    if (op == "BEGIN") {
      stack.add(-1);
    } else if (op == "COMMIT") {
      int markerIndex = stack.lastIndexOf(-1);
      if (markerIndex != -1) {
        stack.removeAt(markerIndex);
      }
    } else if (op == "ROLLBACK") {
      while (stack.isNotEmpty) {
        Object top = stack.removeLast();
        if (top == -1) break;
        List<int> change = top as List<int>;
        buckets[change[0]] = change[1];
      }
    } else if (op.startsWith("INSERT ")) {
      int bucket = int.parse(op.substring(7));
      if (bucket >= 0 && bucket < buckets.length) {
        stack.add([bucket, buckets[bucket]]);
        buckets[bucket]++;
        if (buckets[bucket] > maxCount) maxCount = buckets[bucket];
      }
    } else if (op.startsWith("DELETE ")) {
      int bucket = int.parse(op.substring(7));
      if (bucket >= 0 && bucket < buckets.length) {
        stack.add([bucket, buckets[bucket]]);
        if (buckets[bucket] > 0) buckets[bucket]--;
      }
    }
  }
  return maxCount;
}

