import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> logDays, int threshold) {
  if (logDays.isEmpty) return [];
  List<int> days = [];
  for (int d in logDays) {
    if (d < 0) continue;
    bool seen = false;
    for (int e in days) {
      if (e == d) {
        seen = true;
        break;
      }
    }
    if (!seen) days.add(d);
  }
  if (days.isEmpty) return [];
  for (int i = 0; i < days.length - 1; i++) {
    for (int j = 0; j < days.length - i - 1; j++) {
      if (days[j] > days[j + 1]) {
        int tmp = days[j];
        days[j] = days[j + 1];
        days[j + 1] = tmp;
      }
    }
  }
  List<int> gaps = [];
  for (int i = 1; i < days.length; i++) {
    int gap = days[i] - days[i - 1] - 1;
    if (gap >= threshold) gaps.add(gap);
  }
  return gaps;
}

