double fn0(List<String> entries) {
  int sum = 0;
  for (String entry in entries) {
    if (entry.isEmpty) continue;
    String type = entry[0].toUpperCase();
    int shift = 0;
    if (type == 'D') shift = 1;
    else if (type == 'C') shift = -1;
    for (int i = 0; i < entry.length; i++) {
      int code = entry.codeUnitAt(i);
      if (code >= 65 && code <= 90) {
        code = (code - 65 + shift) % 26;
        if (code < 0) code += 26;
        code += 65;
      } else if (code >= 97 && code <= 122) {
        code = (code - 97 + shift) % 26;
        if (code < 0) code += 26;
        code += 97;
      }
      sum += code;
    }
  }
  return sum / 2.0;
}

