import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> signalGrid) {
  if (signalGrid.isEmpty || signalGrid[0].isEmpty) {
    return 0.0;
  }

  double totalScore = 0.0;
  List<List<int>> directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  int toBin(int value) {
    if (value >= 75) return 4;
    if (value >= 50) return 3;
    if (value >= 25) return 2;
    if (value > 0) return 1;
    return 0;
  }

  for (int r = 0; r < signalGrid.length; r++) {
    for (int c = 0; c < signalGrid[r].length; c++) {
      int bin = toBin(signalGrid[r][c]);
      double cellScore = bin * 0.25;
      int matchingNeighbors = 0;

      for (List<int> d in directions) {
        int nr = r + d[0];
        int nc = c + d[1];

        if (nr >= 0 && nr < signalGrid.length && nc >= 0 && nc < signalGrid[nr].length) {
          if (toBin(signalGrid[nr][nc]) == bin) {
            matchingNeighbors++;
          }
        }
      }

      if (matchingNeighbors >= 2) {
        cellScore += 0.25;
      } else if (matchingNeighbors == 0 && cellScore >= 0.5) {
        cellScore -= 0.25;
      }

      totalScore += cellScore;
    }
  }

  return totalScore;
}

