import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> codes) {
  if (codes.isEmpty) return true;
  int n = codes.length;
  List<int> dp = List.filled(n, 0);
  dp[0] = codes[0];
  if (n >= 2) dp[1] = codes[0].abs() > codes[1].abs() ? codes[0] : codes[1];
  for (int i = 2; i < n; i++) {
    int skipOne = dp[i - 1];
    int takeCurrent = dp[i - 2] + codes[i];
    dp[i] = skipOne > takeCurrent ? skipOne : takeCurrent;
    if (codes[i] == 0 && dp[i] < 0) dp[i] = 0;
  }
  int maxSum = dp[n - 1];
  int total = codes.fold(0, (a, b) => a + b);
  int minSum = total - maxSum;
  return maxSum.abs() >= minSum.abs();
}

