import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  int n = 4;

  List<List<int>> dist = [
    [0, 10, 15, 20],
    [10, 0, 35, 25],
    [15, 35, 0, 30],
    [20, 25, 30, 0]
  ];

  void generatePermutations(
      List<int> current, List<int> remaining, List<List<int>> results) {
    if (remaining.isEmpty) {
      results.add(List.from(current));
      return;
    }
    for (int i = 0; i < remaining.length; i++) {
      int item = remaining.removeAt(i);
      current.add(item);
      generatePermutations(current, remaining, results);
      current.removeLast();
      remaining.insert(i, item);
    }
  }

  List<int> cities = [];
  for (int i = 1; i < n; i++) {
    cities.add(i);
  }

  List<List<int>> permutations = [];
  generatePermutations([], cities, permutations);

  int minCost = 9223372036854775807; 
  List<int>? minPath;

  for (var perm in permutations) {

    List<int> path = [0, ...perm, 0];

    int cost = 0;
    for (int i = 0; i < path.length - 1; i++) {
      cost += dist[path[i]][path[i + 1]];
    }

    if (cost < minCost) {
      minCost = cost;
      minPath = path;
    }
  }

  print('Minimum cost: $minCost');
  print('Path: $minPath');
}

