import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<List<int>> cards, int tableWidth, int tableHeight) {
  if (cards.isEmpty) return true;

  List<List<int>> rects = [];
  for (var card in cards) {
    int x = card[0], y = card[1], rot = card[2];
    int w = rot == 0 ? 2 : 3;
    int h = rot == 0 ? 3 : 2;
    if (x < 0 || y < 0 || x + w > tableWidth || y + h > tableHeight) return false;
    rects.add([x, y, x + w, y + h]);
  }

  for (int i = 0; i < rects.length; i++) {
    for (int j = i + 1; j < rects.length; j++) {
      if (rects[i][0] < rects[j][2] && rects[j][0] < rects[i][2] &&
          rects[i][1] < rects[j][3] && rects[j][1] < rects[i][3]) {
        return false;
      }
    }
  }

  bool sharesEdge(List<int> a, List<int> b) {
    if (a[2] == b[0] || b[2] == a[0]) {
      int ys = a[1] > b[1] ? a[1] : b[1];
      int ye = a[3] < b[3] ? a[3] : b[3];
      if (ys < ye) return true;
    }
    if (a[3] == b[1] || b[3] == a[1]) {
      int xs = a[0] > b[0] ? a[0] : b[0];
      int xe = a[2] < b[2] ? a[2] : b[2];
      if (xs < xe) return true;
    }
    return false;
  }

  List<bool> visited = List.filled(rects.length, false);
  List<int> queue = [0];
  visited[0] = true;
  int count = 1;
  while (queue.isNotEmpty) {
    int curr = queue.removeAt(0);
    for (int j = 0; j < rects.length; j++) {
      if (!visited[j] && sharesEdge(rects[curr], rects[j])) {
        visited[j] = true;
        queue.add(j);
        count++;
      }
    }
  }

  return count == rects.length;
}

