import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String tree) {
  List<String> tokens = tree.split('').where((c) => c.trim().isNotEmpty).toList();

  List<int> parse() {
    if (tokens.isEmpty) return [0, 0, 0];
    String token = tokens.removeAt(0);

    if (token == '(') {
      List<int> sum = [0, 0, 0];
      for (int i = 0; i < 4; i++) {
        List<int> child = parse();
        for (int j = 0; j < 3; j++) {
          sum[j] += child[j];
        }
      }
      if (tokens.isNotEmpty && tokens.first == ')') {
        tokens.removeAt(0);
      }
      return [sum[0] ~/ 4, sum[1] ~/ 4, sum[2] ~/ 4];
    } else if (token == 'R') {
      return [255, 0, 0];
    } else if (token == 'G') {
      return [0, 255, 0];
    } else if (token == 'B') {
      return [0, 0, 255];
    } else if (token == 'W') {
      return [255, 255, 255];
    } else {
      return [0, 0, 0];
    }
  }

  return parse();
}

