import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String signalSequence) {
  final List<String> stack = [];
  const Map<String, String> pairs = {
    '(': ')',
    '[': ']',
    '{': '}'
  };
  const Map<String, int> values = {
    'w': 1,
    'm': 2,
    's': 3
  };
  int i = 0;
  while (i < signalSequence.length) {
    String ch = signalSequence[i];
    if (pairs.containsKey(ch)) {
      stack.add(ch);
      i++;
    } else if (ch == ')' || ch == ']' || ch == '}') {
      if (stack.isEmpty) return false;
      String last = stack.removeLast();
      if (pairs[last] != ch) return false;
      i++;
    } else if (ch == 'w' || ch == 'm' || ch == 's') {
      if (i + 1 >= signalSequence.length) return false;
      String next = signalSequence[i + 1];
      if (next != '(' && next != '[') return false;
      String openBracket = next;
      String closeBracket = pairs[openBracket]!;
      int innerStart = i + 2;
      int depth = 1;
      int j = innerStart;
      while (j < signalSequence.length && depth > 0) {
        String innerCh = signalSequence[j];
        if (innerCh == openBracket) {
          depth++;
        } else if (innerCh == closeBracket) {
          depth--;
        }
        j++;
      }
      if (depth != 0) return false;
      int innerEnd = j - 1;
      int sum = 0;
      for (int k = innerStart; k < innerEnd; k++) {
        String c = signalSequence[k];
        if (values.containsKey(c)) {
          sum += values[c]!;
        }
      }
      if (sum > 4) return false;
      i = j;
    } else {
      return false;
    }
  }
  return stack.isEmpty;
}

