@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<String> items = ['a', 'b', 'c', 'd'];
  int k = 2;

  int n = items.length;
  if (k < 0 || k > n) {
    print('Invalid combination size.');
    return;
  }

  List<List<String>> combinations = [];

  List<int> indices = List<int>.generate(k, (i) => i);

  while (true) {

    combinations.add(indices.map((i) => items[i]).toList());

    int i;
    for (i = k - 1; i >= 0; i--) {
      if (indices[i] < i + n - k) {
        break;
      }
    }

    if (i < 0) {
      break;
    }

    indices[i]++;

    for (int j = i + 1; j < k; j++) {
      indices[j] = indices[j - 1] + 1;
    }
  }

  for (var combo in combinations) {
    print(combo);
  }
}

