import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<String> rows) {
  List<int> order = List<int>.generate(rows.length, (int i) => i);

  int filledCount(String row) {
    int count = 0;
    for (int i = 0; i < row.length; i++) {
      if (row[i] != ' ') {
        count++;
      }
    }
    return count;
  }

  int blockCount(String row) {
    int blocks = 0;
    bool inside = false;
    for (int i = 0; i < row.length; i++) {
      if (row[i] != ' ') {
        if (!inside) {
          blocks++;
          inside = true;
        }
      } else {
        inside = false;
      }
    }
    return blocks;
  }

  bool centerFilled(String row) {
    if (row.isEmpty) {
      return false;
    }
    return row[row.length ~/ 2] != ' ';
  }

  order.sort((int a, int b) {
    String rowA = rows[a];
    String rowB = rows[b];

    int filledA = filledCount(rowA);
    int filledB = filledCount(rowB);
    if (filledA != filledB) {
      return filledB - filledA;
    }

    int blocksA = blockCount(rowA);
    int blocksB = blockCount(rowB);
    if (blocksA != blocksB) {
      return blocksA - blocksB;
    }

    bool centerA = centerFilled(rowA);
    bool centerB = centerFilled(rowB);
    if (centerA != centerB) {
      return centerA ? -1 : 1;
    }

    if (rowA.length != rowB.length) {
      return rowA.length - rowB.length;
    }

    return a - b;
  });

  return order;
}

