import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String log, String sku, String location) {
  if (log.isEmpty) {
    return "LOC:$location|SKU:$sku|NET:+0";
  }

  int netQty = 0;
  List<String> records = log.split(';');

  for (String record in records) {
    if (record.trim().isEmpty) continue;

    Map<String, String> fields = {};
    List<String> parts = record.split('|');
    for (String part in parts) {
      List<String> kv = part.split(':');
      if (kv.length >= 2) {
        fields[kv[0].trim()] = kv.sublist(1).join(':').trim();
      }
    }

    if (fields['SKU'] != sku) continue;

    int qty = int.tryParse(fields['QTY'] ?? '0') ?? 0;

    if (fields['FROM'] == location) {
      netQty -= qty;
    }
    if (fields['TO'] == location) {
      netQty += qty;
    }
  }

  String sign = netQty >= 0 ? '+' : '';
  return "LOC:$location|SKU:$sku|NET:$sign$netQty";
}

