import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<int> cellMasks, int width) {
  int rotateMask(int mask) {
    int newMask = 0;
    if ((mask & 1) != 0) newMask |= 2;
    if ((mask & 2) != 0) newMask |= 4;
    if ((mask & 4) != 0) newMask |= 8;
    if ((mask & 8) != 0) newMask |= 1;
    int pop = 0; int t = newMask; while (t > 0) { pop += t & 1; t >>= 1; }
    return newMask;
  }
  List<String> results = [];
  List<int> current = cellMasks.toList();
  for (int r = 0; r < 4; r++) {
    String repr = '';
    for (int i = 0; i < current.length; i++) {
      repr += current[i].toString();
      if (i < current.length - 1) repr += ',';
    }
    results.add(repr);
    List<int> nextMasks = [];
    for (int m in current) {
      nextMasks.add(rotateMask(m));
    }
    current = nextMasks;
  }
  return results;
}

