import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> keyPositions, List<List<int>> exclusionRects) {
  if (keyPositions.isEmpty) {
    return {
      'totalManhattan': 0,
      'bboxArea': 0,
      'pointsInExclusion': 0,
      'maxSegmentManhattan': 0,
      'turnCount': 0,
    };
  }
  int totalManhattan = 0;
  int maxSegmentManhattan = 0;
  int pointsInExclusion = 0;
  int minX = keyPositions[0][0], maxX = keyPositions[0][0];
  int minY = keyPositions[0][1], maxY = keyPositions[0][1];
  for (var pos in keyPositions) {
    if (pos[0] < minX) minX = pos[0];
    if (pos[0] > maxX) maxX = pos[0];
    if (pos[1] < minY) minY = pos[1];
    if (pos[1] > maxY) maxY = pos[1];
    for (var rect in exclusionRects) {
      if (pos[0] >= rect[0] && pos[0] <= rect[2] &&
          pos[1] >= rect[1] && pos[1] <= rect[3]) {
        pointsInExclusion++;
        break;
      }
    }
  }
  List<List<int>> dirs = [];
  for (int i = 0; i < keyPositions.length - 1; i++) {
    int dx = keyPositions[i + 1][0] - keyPositions[i][0];
    int dy = keyPositions[i + 1][1] - keyPositions[i][1];
    int manhattan = dx.abs() + dy.abs();
    totalManhattan += manhattan;
    if (manhattan > maxSegmentManhattan) maxSegmentManhattan = manhattan;
    if (dx != 0 || dy != 0) {
      dirs.add([dx > 0 ? 1 : (dx < 0 ? -1 : 0),
                dy > 0 ? 1 : (dy < 0 ? -1 : 0)]);
    }
  }
  int turnCount = 0;
  for (int i = 0; i < dirs.length - 1; i++) {
    if (dirs[i][0] != dirs[i + 1][0] || dirs[i][1] != dirs[i + 1][1]) {
      turnCount++;
    }
  }
  return {
    'totalManhattan': totalManhattan,
    'bboxArea': (maxX - minX) * (maxY - minY),
    'pointsInExclusion': pointsInExclusion,
    'maxSegmentManhattan': maxSegmentManhattan,
    'turnCount': turnCount,
  };
}

