import 'dart:convert';
import 'dart:async';
import 'dart:io';
import 'dart:math';

/// Simulated coordinates for demonstration purposes.
class Location {
  final double latitude;
  final double longitude;

  Location(this.latitude, this.longitude);

  double distanceTo(Location other) {

    const earthRadius = 6371000; 
    final dLat = _degToRad(other.latitude - latitude);
    final dLon = _degToRad(other.longitude - longitude);

    final a = sin(dLat / 2) * sin(dLat / 2) +
        cos(_degToRad(latitude)) *
            cos(_degToRad(other.latitude)) *
            sin(dLon / 2) *
            sin(dLon / 2);
    final c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return earthRadius * c;
  }

  static double _degToRad(double deg) => deg * pi / 180;
}

class Geofence {
  final String id;
  final Location center;
  final double radiusMeters;
  final String message;

  Geofence(this.id, this.center, this.radiusMeters, this.message);

  bool contains(Location location) {
    return center.distanceTo(location) <= radiusMeters;
  }
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() async {

  final geofences = [
    Geofence(
        'park',
        Location(37.7749, -122.4194), 
        300,
        'You have arrived at the park!'),
    Geofence(
        'cafe',
        Location(37.7765, -122.4170),
        150,
        'Welcome to your favorite cafe!'),
  ];

  final simulatedPath = [
    Location(37.7700, -122.4300), 
    Location(37.7740, -122.4200), 
    Location(37.7750, -122.4180), 
    Location(37.7766, -122.4171), 
    Location(37.7749, -122.4194), 
  ];

  final triggered = <String>{};

  print('Simulating location-based push notifications...\n');

  for (final location in simulatedPath) {
    print('Current location: (${location.latitude}, ${location.longitude})');
    for (final geofence in geofences) {
      if (geofence.contains(location) && !triggered.contains(geofence.id)) {
        _sendPushNotification(geofence.message);
        triggered.add(geofence.id);
      }
    }
    await Future.delayed(Duration(seconds: 2));
  }

  print('\nSimulation complete.');
}

void _sendPushNotification(String message) {

  print('🔔 PUSH NOTIFICATION: $message');
}

