import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> signalReadings, int radius) {
  final readings = List<int>.of(signalReadings)..sort();
  final n = readings.length;
  if (n == 0) return {0};

  final valid = List.generate(n, (_) => List<bool>.filled(n, false));
  for (var i = 0; i < n; i++) {
    for (var j = i; j < n; j++) {
      for (var k = i; k <= j; k++) {
        final center = readings[k];
        if (readings[j] - center <= radius && center - readings[i] <= radius) {
          valid[i][j] = true;
          break;
        }
      }
    }
  }

  Set<int> dfs(int start) {
    if (start == n) return {0};

    final result = <int>{};
    for (var end = start; end < n; end++) {
      if (valid[start][end]) {
        for (final count in dfs(end + 1)) {
          result.add(count + 1);
        }
      }
    }
    return result;
  }

  return dfs(0);
}

