import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String sequence) {
  int n = sequence.length;
  if (n % 2 != 0) return false;
  if (n == 0) return true;
  bool isValidPair(String a, String b) {
    String p = a + b;
    return p == 'AT' || p == 'TA' || p == 'CG' || p == 'GC';
  }
  List<List<bool>> dp = List.generate(n, (_) => List<bool>.filled(n, false));
  for (int i = 0; i < n - 1; i++) {
    if (isValidPair(sequence[i], sequence[i + 1])) {
      dp[i][i + 1] = true;
    }
  }
  for (int length = 4; length <= n; length += 2) {
    for (int i = 0; i <= n - length; i++) {
      int j = i + length - 1;
      if (isValidPair(sequence[i], sequence[j]) && dp[i + 1][j - 1]) {
        dp[i][j] = true;
        continue;
      }
      for (int k = i + 1; k < j; k += 2) {
        if (dp[i][k] && dp[k + 1][j]) {
          dp[i][j] = true;
          break;
        }
      }
    }
  }
  return dp[0][n - 1];
}

