import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<String> matches, int targetScore) {
  final Map<String, int> wins = {};
  final Map<String, Set<String>> defeated = {};
  final Set<String> allPlayers = {};

  for (final match in matches) {
    final parts = match.split(':');
    if (parts.length == 2) {
      final winner = parts[0].trim();
      final loser = parts[1].trim();

      allPlayers.add(winner);
      allPlayers.add(loser);

      wins[winner] = (wins[winner] ?? 0) + 1;
      defeated.putIfAbsent(winner, () => {}).add(loser);
    }
  }

  int count = 0;
  for (final player in allPlayers) {
    final pWins = wins[player] ?? 0;
    final pDefeatedCount = defeated[player]?.length ?? 0;
    if (pWins * pDefeatedCount == targetScore) {
      count++;
    }
  }

  return count;
}

