List<int> fn0(List<String> logLines) {
  List<int> stack = [];
  List<int> results = [];
  for (String line in logLines) {
    if (line.startsWith('START ')) {
      stack.add(int.parse(line.substring(6)));
    } else if (line == 'END' && stack.isNotEmpty) {
      stack.removeLast();
    } else if (line == 'STATUS') {
      results.add(stack.isEmpty ? 0 : stack.last);
    }
  }
  return results;
}

