import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<List<int>> schedule, int preheatMinutes) {
  const weekMinutes = 7 * 1440;
  final Set<int> activeDays = {};
  for (final entry in schedule) {
    final day = entry[0];
    final start = entry[1];
    final duration = entry[2];
    if (duration + preheatMinutes >= weekMinutes) {
      for (int d = 0; d < 7; d++) {
        activeDays.add(d);
      }
      continue;
    }
    int absStart = day * 1440 + start - preheatMinutes;
    int absEnd = day * 1440 + start + duration;
    absStart = ((absStart % weekMinutes) + weekMinutes) % weekMinutes;
    absEnd = ((absEnd % weekMinutes) + weekMinutes) % weekMinutes;
    if (absStart < absEnd) {
      for (int m = absStart; m < absEnd; m++) {
        activeDays.add(m ~/ 1440);
      }
    } else if (absStart > absEnd) {
      for (int m = absStart; m < weekMinutes; m++) {
        activeDays.add(m ~/ 1440);
      }
      for (int m = 0; m < absEnd; m++) {
        activeDays.add(m ~/ 1440);
      }
    }
  }
  final result = activeDays.toList()..sort();
  return result;
}

