void fn0() {
  bool condition = true;

  List<int> myList = [
    1,
    2,
    if (condition) 3,
    for (int i = 4; i <= 6; i++) i,
  ];
  print('List: $myList'); 

  Set<String> mySet = {
    'a',
    'b',
    if (condition) 'c',
    for (String s in ['d', 'e']) s,
  };
  print('Set: $mySet'); 

  Map<String, int> myMap = {
